        // Initializing with parseDocumentation = true
        builder = new JSDocInfoBuilder(true);
    }



    /**
     * Tests the case where addAuthor returns false.
     * This happens when currentInfo.documentAuthor(author) is false.
     */
    @Test
    public void testAddAuthor_ReturnsFalseWhenAuthorDoesNotExist() {
        String authorName = "NonExistentAuthor";

        // By default, a new builder should not have this author.
        boolean result = builder.addAuthor(authorName);

        assertFalse("Method should return false when author is not in currentInfo", result);
